typedef struct { float x, y, z, w; } FanPt;
typedef struct {
    char pad0[0x210];
    FanPt base;   /* 0x210; w = timer */
    FanPt dir;    /* 0x220 */
    FanPt pts[16]; /* 0x230 */
} FanData;

/* Shared moby update: steps the timer at 0x21C, spaces 16 entries, and runs the pair checks. */
void update_blarg_space_commando_beam(void *arg) {
    char *moby = arg;
    FanData *data = ((FanData *)((Moby *)moby)->pvars);
    int x;
    float A[4];
    float W[4];
    ShotInfo rec;
    float scale;
    float t;
    int i, j, k, m;
    int n;

    x = truncate_float_to_s32(data->base.w);
    fast_dec_timer((s32 *)&x);
    data->base.w = (float)x;
    if (x == 0) {
        return;
    }
    if (x == 20) {
        char *p = (char *)data;
        for (n = 15; n >= 0; n--) {
            if (1.0f <= *(float *)(p + 0x23C)) {
                *(float *)(p + 0x23C) = 0.98f;
            }
            p += 0x10;
        }
    }

    for (i = 0; i < 16; i++) {
        char *e;
        if (g_hero.vehicle_mode == 1) {
            scale = (*(float *)&space_commando_beam_spread_speed * g_frame_time) * 0.5f;
        } else {
            scale = *(float *)&space_commando_beam_spread_speed * g_frame_time;
        }
        FastVecSub(A, &data->pts[i], &data->base);
        A[2] = 0.0f;
        vec_scale_to_length(A, A, scale);
        FastVecAdd(A, (float *)&data->pts[i], A);
        FastVecSub(W, A, &((Moby *)moby)->pos);
        t = FastVecDot(W, &data->dir);
        if (0.4f < t) {
            A[2] = A[2] - (g_frame_time + g_frame_time);
        } else if (t < 0.3f) {
            A[2] = A[2] + (g_frame_time + g_frame_time);
        }
        e = (char *)data + i * 16;
        if (1.0f <= *(float *)(e + 0x23C) && coll_line(&data->pts[i], A, 2, 0, 0)) {
            A[3] = 0.98f;
        } else if (A[3] < 1.0f) {
            ApproachValue(&A[3], 0.0f, g_frame_time + g_frame_time);
        }
        qcopy(&data->pts[i], A);
    }

    j = 0;
    do {
        char *e = (char *)data + j * 16;
        char *f;
        k = j + 1;
        if (0.6f <= *(float *)(e + 0x23C)) {
            f = (char *)data + k * 16;
            if (0.6f <= *(float *)(f + 0x23C)) {
                A[0] = FastCos(((Moby *)moby)->rot.z);
                A[1] = FastSin(((Moby *)moby)->rot.z);
                A[2] = 1.0f;
                A[3] = 5627.925f;
                m = 0x10000;
                if (1.0f <= *(float *)(e + 0x23C) && 1.0f <= *(float *)(f + 0x23C)) {
                    m = 0x10001;
                }
                InitDirectionalHitQuery(&rec, (struct Moby *)moby, m, A, 1.0f);
                rec.oclass = ((Moby *)moby)->oclass;
                rec.unk18 = 0;
                rec.unk19 = 1;
                coll_line(&data->pts[j], &data->pts[j + 1], 0, moby, &rec);
            }
        }
        j = k;
    } while (j < 15);

    AddDrawCallback((void *)DrawBeam, moby);
    spawn_blarg_space_commando_beam_sparks(moby);
}
