/* Draws the beam as 15 textured quads between consecutive points of the moby's point list (data + 0x230), each twice: once with the odd corners pulled toward the centre (data + 0x210) and once raised by 0.25.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/gameplay/entities/002fdbd0.c, FUN_L06_002ff680. */
void DrawBeam(char *moby) {
    char *data = ((char *)((Moby *)moby)->pvars);
    QuadPacket_f680 pk[2];
    f32 mat[4][4];
    f32 tmp[4];
    s32 i;
    s32 j;
    s32 off;
    f32 *v;
    u64 regs;

    VU1_addGSregister(0x47, 0x5380B);
    i = 0;
    pk[0].tag[1] = GetEffectTex((*(s32 *)&space_commando_beam_texture));
    pk[1].tag[1] = GetEffectTex((*(s32 *)&space_commando_beam_texture));
    regs = (*(s32 *)&beam_blend_minuend_selector_gp);
    regs |= (u64)(*(s32 *)&beam_blend_subtrahend_selector_gp) << 2;
    regs |= (u64)(*(s32 *)&beam_blend_alpha_multiplier_selector_gp) << 4;
    regs |= (u64)(*(s32 *)&beam_blend_addend_selector_gp) << 6;
    regs |= (u64)(*(s32 *)&beam_blend_fixed_alpha_gp) << 32;
    /* Store order is load-bearing: it sets which register keeps regs. */
    pk[1].tag[2] = 0x0000FF9000000260ULL;
    pk[0].tag[2] = 0x0000FF9000000260ULL;
    pk[1].tag[0] = 0;
    pk[0].tag[0] = 0;
    pk[1].tag[3] = regs;
    pk[0].tag[3] = regs;
    set_identity_matrix(mat);
    do {
        space_commando_beam_uvs[1][1] = space_commando_beam_uvs[3][1];
        space_commando_beam_uvs[3][1] = random_float_between(0.0f, 0.2f);
        for (j = 0; j < 4; j++) {
            v = pk[0].pos[j];
            off = (i + j / 2) * 16;
            /* &data[...] (not data + off + ...) keeps retail's off + data add. */
            qcopy(v, &data[off + 0x230]);
            /* The colour call in both arms: retail merges the two calls and
               leaves the address add in each arm. */
            if (j & 1) {
                FastVecSub(tmp, v, data + 0x210);
                vec_scale_to_length(tmp, tmp, 0.5f);
                FastVecSub(v, v, tmp);
                v[2] -= 0.125f;
                pk[0].col[j] = FastTweenColor_r(*(f32 *)(data + off + 0x23C), (*(s32 *)&space_commando_beam_inner_color_a),
                                                (*(s32 *)&space_commando_beam_inner_color_b));
            } else {
                pk[0].col[j] = FastTweenColor_r(*(f32 *)(data + off + 0x23C), (*(s32 *)&space_commando_beam_outer_color_a),
                                                (*(s32 *)&space_commando_beam_outer_color_b));
            }
            pk[0].uv[j][0] = space_commando_beam_uvs[j][0];
            pk[0].uv[j][1] = space_commando_beam_uvs[j][1];
            pk[1].uv[j][0] = space_commando_beam_uvs[j][0];
            pk[1].uv[j][1] = space_commando_beam_uvs[j][1];
        }
        draw_world_quad(pk, mat, 0);
        for (j = 0; j < 4; j++) {
            v = pk[0].pos[j];
            if (j & 1) {
                v[2] += 0.25f;
            }
        }
        i++;
        draw_world_quad(pk, mat, 0);
    } while (i < 15);
    VU1_addGSregister(0x47, 0x5360B);
}
