        d = blarg_zero_vec;
        spawn_proximity_gated_bolts(moby);
        a = (char *)&moby->pos;
        b = (char *)&moby->rot;
        SpawnBreakFragment(moby, 0x679, a, b, 0, 0, z, d, d, d);
        SpawnBreakFragment(moby, 0x67A, a, b, 0, 0, z, d, d, d);
        SpawnBreakFragment(moby, 0x67B, a, b, 0, 0, z, d, d, d);
        m = (Moby *)CreateMoby(0x678);
